S = "Hakeem Force Academy"
QS = [
(S, "On what date was the World Health Organization (WHO) established?", ["7 April 1948", "24 October 1945", "10 December 1948", "1 January 1946"], 0, "The WHO constitution came into force on 7 April 1948, which is why World Health Day is observed every year on 7 April. The WHO was set up as a specialised agency of the United Nations.", "The WHO headquarters is in Geneva, Switzerland.", [4118]),
(S, "On what date was the Water and Power Development Authority (WAPDA) of Pakistan established?", ["12 February 1958", "14 August 1947", "23 March 1956", "5 July 1960"], 0, "WAPDA was created by an Act in 1958 and began functioning on 12 February 1958. It was formed to develop Pakistan's water and power resources.", "WAPDA was later split so that power distribution moved to separate companies, but it still builds dams such as Tarbela and Mangla.", [4117]),
(S, "What is the closest meaning of the word 'eventually'?", ["Ultimately", "Suddenly", "Rarely", "Immediately"], 0, "'Eventually' means at last, after a long time or a series of events. 'Ultimately' carries the same sense.", "Another synonym of 'eventually' is 'finally'.", [3263, 3714]),
(S, "In which country does Mount Everest, the highest peak in the world, mainly lie?", ["Nepal", "Pakistan", "India", "Bhutan"], 0, "Mount Everest lies in the Himalayas on the border between Nepal and the Tibet region of China. The main summit is usually described as being in Nepal.", "Everest is about 8,849 metres high; Nepal calls it Sagarmatha and Tibet calls it Chomolungma.", [2206]),
(S, "What is the measure of each angle of a square?", ["90 degrees", "60 degrees", "45 degrees", "180 degrees"], 0, "A square has four equal sides and four equal angles. The angles of a four-sided figure add up to 360 degrees, so each is 360 divided by 4 = 90 degrees.", "A rectangle also has four right angles.", [3046]),
(S, "On what date did the War of Independence of 1857 begin at Meerut?", ["10 May 1857", "23 June 1857", "14 August 1857", "1 January 1858"], 0, "The sepoys of the Bengal Army at Meerut revolted on 10 May 1857, and this started the War of Independence. The rebels then marched to Delhi.", "The last Mughal emperor, Bahadur Shah Zafar, was declared the leader of the rebellion.", [3379]),
(S, "What is the antonym (opposite) of the word 'excuse' used as a verb meaning to forgive?", ["Accuse", "Pardon", "Forgive", "Overlook"], 0, "To excuse means to forgive or let go without blame. Its opposite is to accuse or blame someone.", "'Condemn' and 'blame' are also opposites of excuse in this sense.", [467]),
(S, "What is the antonym (opposite) of the word 'exhibit'?", ["Conceal", "Display", "Show", "Present"], 0, "To exhibit means to show openly. Its opposite is to conceal or hide.", "An exhibition is a public show of things.", [899, 3617]),
(S, "What is the closest meaning (synonym) of the word 'exhibit'?", ["Display", "Hide", "Destroy", "Forget"], 0, "To exhibit means to show something publicly. 'Display' has the same meaning.", "'Exhibit' can also be a noun meaning an object shown in a museum or court.", [3264, 3508, 1304]),
(S, "What is the closest meaning of the word 'exponent'?", ["Advocate", "Opponent", "Spectator", "Critic"], 0, "An exponent is a person who explains or promotes an idea or cause, so an advocate is the closest meaning. An opponent is the opposite.", "In mathematics, an exponent is the small raised number that shows the power of a base.", [3265, 1027]),
(S, "Which product is Pakistan's largest export by value?", ["Textiles and clothing", "Wheat", "Rice", "Fruits"], 0, "Textiles, including cotton cloth, yarn, bed linen and readymade garments, make up more than half of Pakistan's exports by value. Rice is the largest food export but is much smaller.", "Pakistan is among the top cotton-producing countries in the world.", [3090]),
(S, "Which country is the largest exporter of coffee in the world?", ["Brazil", "Colombia", "Vietnam", "Ethiopia"], 0, "Brazil grows and sells more coffee than any other country, around one third of the world's supply. Vietnam is second.", "Vietnam is the world's largest exporter of Robusta coffee.", [4347]),
(S, "In which year was Facebook founded?", ["2004", "2002", "2006", "2008"], 0, "Mark Zuckerberg launched Facebook on 4 February 2004 from his Harvard University dormitory.", "The company was renamed Meta Platforms in 2021.", [2369]),
(S, "What is the value of 10! (factorial of 10)?", ["3628800", "362880", "39916800", "720720"], 0, "10! = 10 x 9 x 8 x 7 x 6 x 5 x 4 x 3 x 2 x 1. Since 9! = 362880, then 10! = 362880 x 10 = 3628800.", "The factorial of 5 is 120.", [3380]),
(S, "Factorise the expression x^2 + 5x - 6.", ["(x + 6)(x - 1)", "(x - 6)(x + 1)", "(x + 3)(x - 2)", "(x + 2)(x - 3)"], 0, "We need two numbers whose product is -6 and whose sum is +5. These numbers are +6 and -1, so x^2 + 5x - 6 = (x + 6)(x - 1).", "The roots of this expression are x = 1 and x = -6.", [1651]),
(S, "What are all the factors of 10?", ["1, 2, 5, 10", "1, 2, 10", "2, 5, 10", "1, 5, 10"], 0, "The factors of a number are the numbers that divide it exactly. 10 divided by 1, 2, 5 and 10 leaves no remainder.", "10 has the prime factors 2 and 5.", [830]),
(S, "Into which sea does the Indus River finally fall?", ["Arabian Sea", "Bay of Bengal", "Red Sea", "Caspian Sea"], 0, "The Indus flows the whole length of Pakistan and enters the Arabian Sea near Keti Bandar in the Indus delta south of Thatta.", "The Indus is about 3,000 km long and rises near Lake Mansarovar in Tibet.", [143]),
(S, "The family tree (lineage) of the Holy Prophet Muhammad (PBUH) goes back to which Prophet?", ["Hazrat Ismail (AS)", "Hazrat Ishaq (AS)", "Hazrat Musa (AS)", "Hazrat Isa (AS)"], 0, "The Prophet (PBUH) belonged to the Quraish and his ancestry is traced through Adnan to Hazrat Ismail (AS), the son of Hazrat Ibrahim (AS).", "The Prophet's ancestry from Adnan to Ismail (AS) is not recorded in full detail, but the link to Ismail (AS) is agreed.", [2717]),
(S, "For what is Sadequain famous?", ["Painting and calligraphy", "Poetry", "Cricket", "Politics"], 0, "Sadequain (1930-1987) was a famous Pakistani painter and calligrapher, known for his Quranic calligraphy and murals.", "He painted the ceiling mural at the Mangla Dam power house and the Frere Hall murals in Karachi.", [2655, 3094, 883, 3096]),
(S, "A train travels at twice the speed of a car. If the car travels at 60 km/h, how far will the train travel in 30 minutes?", ["60 km", "30 km", "120 km", "90 km"], 0, "The train's speed is 2 x 60 = 120 km/h. In 30 minutes (half an hour) it covers 120 x 1/2 = 60 km.", "Distance equals speed multiplied by time.", [1386, 1388, 1342]),
(S, "A train's speed is twice that of a car. If the car covers 60 km in 60 minutes, how far does the train cover in the same time?", ["120 km", "60 km", "30 km", "180 km"], 0, "The car's speed is 60 km in 1 hour = 60 km/h. The train moves at twice this speed, 120 km/h, so it covers 120 km in 60 minutes.", "60 minutes equal 1 hour.", [620]),
(S, "A train's speed is twice that of a car, and the train covers 120 km in 1 hour. How far does the car travel in 15 minutes?", ["15 km", "30 km", "60 km", "7.5 km"], 0, "The train's speed is 120 km/h, so the car's speed is 120 / 2 = 60 km/h. In 15 minutes (a quarter of an hour) the car covers 60 / 4 = 15 km.", "15 minutes are one quarter of an hour.", [622]),
(S, "In which surah of the Holy Quran are the faraiz (obligatory acts) of wudu mentioned?", ["Surah Al-Maidah", "Surah Al-Baqarah", "Surah An-Nisa", "Surah Al-Anfal"], 0, "The faraiz of wudu are described in verse 6 of Surah Al-Maidah, which orders washing the face and arms, wiping the head and washing the feet.", "The same verse also gives the command for tayammum when water is not available; Surah An-Nisa (4:43) also mentions tayammum.", [2300, 413, 2318, 2302, 2303]),
(S, "In which Hijri year was Hajj made fard (obligatory) on Muslims?", ["9 AH", "2 AH", "6 AH", "11 AH"], 0, "Most Pakistani textbooks say Hajj became fard in 9 AH, after the revelation of Surah Aal-e-Imran verse 97. The Prophet (PBUH) performed his only Hajj, the Farewell Hajj, in 10 AH.", "Some scholars give 6 AH or 10 AH, so sources differ.", [2246]),
(S, "How many faraiz (obligatory acts) of namaz are there according to Hanafi fiqh?", ["13", "7", "6", "12"], 0, "Hanafi fiqh counts 13 faraiz of namaz: 7 before the prayer (conditions) and 6 inside the prayer (pillars).", "The 6 inside the prayer are takbeer-e-tahrima, qiyam, qirat, ruku, sajdah and qa'da akhira.", [1819]),
(S, "A farm has 3 goats, 5 cows and 14 hens. What is the total number of legs of these animals?", ["60", "56", "64", "46"], 0, "Goats and cows have 4 legs each: (3 + 5) x 4 = 32 legs. Hens have 2 legs each: 14 x 2 = 28 legs. The total is 32 + 28 = 60.", "The count of the farmer's legs is not included.", [1997]),
(S, "What does Radd-ul-Fasaad, the name of the Pakistan Army operation launched in 2017, mean?", ["Elimination of discord (mischief)", "Defeat of the enemy", "Thunder strike", "Sword of the Prophet"], 0, "Radd-ul-Fasaad is Arabic and means rejecting or eliminating discord and mischief. The operation was launched in February 2017 to remove the remaining terrorism and strengthen border security.", "Operation Zarb-e-Azb (2014) was the earlier major operation in North Waziristan.", [281]),
(S, "Who was the first person to fly faster than the speed of sound?", ["Chuck Yeager", "Neil Armstrong", "Yuri Gagarin", "Charles Lindbergh"], 0, "US Air Force pilot Chuck Yeager broke the sound barrier on 14 October 1947 flying the Bell X-1 rocket plane.", "The speed of sound at sea level is about 1,235 km/h, called Mach 1.", [5121]),
(S, "Which is the fastest animal on earth?", ["Peregrine falcon", "Cheetah", "Eagle", "Greyhound"], 0, "The peregrine falcon reaches over 320 km/h in its hunting dive, which is faster than any other animal. The cheetah is the fastest land animal at about 110 km/h.", "The cheetah can keep its top speed only for short distances.", [955]),
(S, "The former Federally Administered Tribal Areas (FATA) became part of which province?", ["Khyber Pakhtunkhwa", "Balochistan", "Punjab", "Sindh"], 0, "FATA was merged into Khyber Pakhtunkhwa through the 25th Constitutional Amendment, passed in May 2018.", "The merged areas were divided into districts such as North Waziristan and South Waziristan.", [1653]),
(S, "What does FATA stand for?", ["Federally Administered Tribal Areas", "Federal Authority of Tribal Affairs", "Frontier Area Tribal Administration", "Federal Agency for Tribal Areas"], 0, "FATA stands for Federally Administered Tribal Areas, the seven agencies on the Afghan border governed directly by the federal government.", "FATA was merged into Khyber Pakhtunkhwa in 2018.", [2897]),
(S, "Where is the headquarters of the Financial Action Task Force (FATF) located?", ["Paris", "Geneva", "New York", "London"], 0, "The FATF secretariat is hosted at the OECD headquarters in Paris, France.", "The FATF was set up by the G7 in 1989 to fight money laundering and terrorist financing.", [4174]),
]
